use serde::{Deserialize, Serialize};
use tokio::sync::mpsc;
use ts_rs::TS;

use super::structured::ShellKind;

/// Opaque handle. Generated by the transport, never by a caller, so a UI bug
/// cannot address a session it was not handed.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize, TS)]
#[serde(transparent)]
#[ts(export, export_to = "generated/")]
pub struct PtySessionId(pub String);

impl PtySessionId {
    pub fn new() -> Self {
        Self(uuid::Uuid::new_v4().to_string())
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl Default for PtySessionId {
    fn default() -> Self {
        Self::new()
    }
}

impl std::fmt::Display for PtySessionId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "generated/")]
pub struct PtySize {
    pub cols: u16,
    pub rows: u16,
}

impl PtySize {
    /// Guards against the 0x0 measurement xterm reports before its first
    /// layout pass, which some platforms treat as a fatal ioctl.
    pub fn sanitised(self) -> Self {
        Self {
            cols: self.cols.max(1),
            rows: self.rows.max(1),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "generated/")]
pub struct PtySpawnSpec {
    /// Working directory. `None` roots the shell at the connection root.
    pub cwd: Option<String>,
    pub size: PtySize,
}

/// The descriptor handed back to the UI when a session opens.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "generated/")]
pub struct PtySession {
    pub id: PtySessionId,
    /// Program actually spawned, e.g. `nu` or `powershell.exe`.
    pub program: String,
    pub shell: ShellKind,
    pub cwd: String,
    pub size: PtySize,
    /// True when `nu` was not on PATH and the platform default shell was
    /// spawned instead. Drives the non-blocking fallback notice.
    pub fell_back: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "generated/")]
pub struct PtyExit {
    pub code: Option<i32>,
    pub success: bool,
}

/// Streamed out of a live session. Delivered to the UI as Tauri events on the
/// desktop build and as WebSocket frames on the agent build.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(tag = "type", content = "data", rename_all = "camelCase")]
#[ts(export, export_to = "generated/")]
pub enum PtyEvent {
    Output(String),
    Exit(PtyExit),
    Error(String),
}

/// What `Transport::open_pty` returns: the serialisable descriptor plus the
/// live event channel. The channel does not cross the wire — the desktop and
/// agent layers each drain it and re-emit `PtyEvent` in their own protocol.
#[derive(Debug)]
pub struct PtyStream {
    pub session: PtySession,
    pub events: mpsc::Receiver<PtyEvent>,
}
